import{apiClient}from"./client";const getOrganizationSlug=()=>localStorage.getItem("organizationSlug"),getStoreRules=async t=>{t=t||getOrganizationSlug();return(await apiClient.get("/admin/store-rules",{params:{organizationSlug:t}})).data},getStoreRule=async(t,e)=>{e=e||getOrganizationSlug();return(await apiClient.get("/admin/store-rules/"+t,{params:{organizationSlug:e}})).data},upsertStoreRule=async(t,e,a)=>{a=a||getOrganizationSlug();return(await apiClient.put("/admin/store-rules/"+t,e,{params:{organizationSlug:a}})).data},deleteStoreRule=async(t,e)=>{e=e||getOrganizationSlug();return(await apiClient.delete("/admin/store-rules/"+t,{params:{organizationSlug:e}})).data};export{getStoreRules,getStoreRule,upsertStoreRule,deleteStoreRule};